-- Bảng "phẳng" xấu: tên và thành phố khách lặp ở mỗi dòng đơn hàng
CREATE TABLE orders_flat (
  order_id INTEGER, customer_name TEXT, customer_city TEXT, product TEXT, qty INTEGER
);
-- Thiết kế đã chuẩn hoá: mỗi sự thật chỉ lưu MỘT lần
CREATE TABLE customer_dim (customer_id INTEGER PRIMARY KEY, name TEXT NOT NULL, city TEXT);
CREATE TABLE order_fact (order_id INTEGER PRIMARY KEY, customer_id INTEGER REFERENCES customer_dim(customer_id));
